	static final byte PATTERN_COUNT = 11;
	static final byte SAMPLE = 12;
	static final byte LEGACY_GUARD = 13;
	static final byte COLD_SYNOPSIS_GUARD = 14;
	static final byte LEARNED_FILTER_GUARD = 15;
	/** Reported when a provider the log read from is no longer the published one. */
